/* C API of the Mojo port of `rational.c`, generated by mojo-anything. */
#ifndef RATIONAL_MOJO_H
#define RATIONAL_MOJO_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

typedef struct { int num; int den; } AVRational;

int av_reduce(int *dst_num, int *dst_den, int64_t num, int64_t den, int64_t max);
AVRational av_mul_q(AVRational b, AVRational c);
AVRational av_div_q(AVRational b, AVRational c);
AVRational av_add_q(AVRational b, AVRational c);
AVRational av_sub_q(AVRational b, AVRational c);
AVRational av_d2q(double d, int max);
int av_nearer_q(AVRational q, AVRational q1, AVRational q2);
uint32_t av_q2intfloat(AVRational q);

/* The same functions under `mojo_anything_` names, for shadow runs. */
int mojo_anything_av_reduce(int *dst_num, int *dst_den, int64_t num, int64_t den, int64_t max);
AVRational mojo_anything_av_mul_q(AVRational b, AVRational c);
AVRational mojo_anything_av_div_q(AVRational b, AVRational c);
AVRational mojo_anything_av_add_q(AVRational b, AVRational c);
AVRational mojo_anything_av_sub_q(AVRational b, AVRational c);
AVRational mojo_anything_av_d2q(double d, int max);
int mojo_anything_av_nearer_q(AVRational q, AVRational q1, AVRational q2);
uint32_t mojo_anything_av_q2intfloat(AVRational q);

#endif /* RATIONAL_MOJO_H */
